steps.command:
mkdir -p /tmp/aud && cat > /tmp/aud/a.py <<'E'
import ast,sys,glob,os
for f in sorted(glob.glob('billing/*.py')):
    m=os.path.basename(f)[:-3]
    t=ast.parse(open(f).read())
    def walk(n,pre):
        for c in ast.iter_child_nodes(n):
            if isinstance(c,(ast.FunctionDef,ast.AsyncFunctionDef)):
                name=pre+c.name
                ann=ast.unparse(c.returns) if c.returns else ''
                rets=[]
                def r(x):
                    for y in ast.iter_child_nodes(x):
                        if isinstance(y,(ast.FunctionDef,ast.AsyncFunctionDef,ast.Lambda,ast.ClassDef)):continue
                        if isinstance(y,ast.Return):rets.append(ast.unparse(y.value) if y.value else 'BARE')
                        r(y)
                r(c)
                last=c.body[-1]
                fall = not isinstance(last,(ast.Return,ast.Raise))
                if ann!='None' and ('None' in ann or any(x in('None','BARE') for x in rets) or (fall and rets)):
                    print(f"{m}.{name} | {ann} | {rets} | fall={fall}")
                walk(c,name+'.')
            elif isinstance(c,ast.ClassDef): walk(c,pre+c.name+'.')
    walk(t,'')
E
cd .. && .venv/bin/python -I /tmp/aud/a.py
